create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),email text unique not null,password_hash text not null,role text not null check(role in('admin','teacher')),created_at timestamptz default now());
create table if not exists applications(id uuid primary key default gen_random_uuid(),application_id text unique not null,first_name text not null,middle_name text,last_name text not null,gender text not null check(gender in('Male','Female')),dob date,fayda_id varchar(16) not null check(fayda_id ~ '^[0-9]{16}$'),phone text not null,region text,woreda text,kebele text,specific_address text,academic_year text not null,grade int not null check(grade between 9 and 12),section text not null,study_option text,student_photo_url text,guardian_full_name text not null,guardian_phone text not null,guardian_fayda_id varchar(16),guardian_photo_url text,status text not null default 'Pending',student_id text unique,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists students(id uuid primary key default gen_random_uuid(),student_id text unique not null,application_id uuid references applications(id),first_name text not null,middle_name text,last_name text not null,full_name text not null,gender text,dob date,fayda_id varchar(16) not null,phone text,region text,woreda text,kebele text,specific_address text,academic_year text not null,grade int not null,section text not null,study_option text,student_photo_url text,guardian_full_name text,guardian_phone text,guardian_fayda_id varchar(16),guardian_photo_url text,admission_date date default current_date,status text default 'Active');
create table if not exists subjects(id uuid primary key default gen_random_uuid(),grade int not null,section text not null,study_option text,subject_name text not null,subject_code text,maximum_mark numeric not null check(maximum_mark>0),created_at timestamptz default now());
create unique index if not exists subjects_unique on subjects(grade,section,coalesce(study_option,''),subject_name);
create table if not exists marks(id uuid primary key default gen_random_uuid(),student_id uuid references students(id) on delete cascade,subject_id uuid references subjects(id) on delete cascade,academic_year text not null,mark numeric null,maximum_mark numeric not null,updated_at timestamptz default now(),unique(student_id,subject_id,academic_year));
create table if not exists site_settings(id int primary key default 1,school_name text default 'Bashasha Secondary School',pass_threshold numeric default 50,academic_year text default '2026');
insert into site_settings(id) values(1) on conflict do nothing;
create table if not exists announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,created_at timestamptz default now());
create table if not exists messages(id uuid primary key default gen_random_uuid(),name text,phone text,email text,message text not null,status text default 'New',created_at timestamptz default now());